local config = {
  ui_story_40180001_1_dialog_content = "Permita que quem possui a noção completa da verdade fale primeiro. Ou seja, eu.",
  ui_story_40180001_2_dialog_content = "Porém, como parte da nobreza aristocrata de Lumópolis, essa questão deve ser tocada por mim.",
  ui_story_40180001_3_dialog_content = "Pelo que discutem, crianças? É claro, uma coisa dessas deve ficar nas mãos de um adulto. Permita-me.",
  ui_story_40180001_4_dialog_content = "Espere, espere...",
  ui_story_40180001_5_dialog_content = "Eu sei que disse que queria ouvir um conto de ninar...",
  ui_story_40180001_6_dialog_content = "Mas eu não esperava esse nível de entusiasmo...",
  ui_story_40180001_7_dialog_content = "<size=36>A verdade acima de tudo!</size>",
  ui_story_40180001_8_dialog_content = "<size=40>Confie na nobreza!</size>",
  ui_story_40180001_9_dialog_content = "<size=44>Antiguidade deve ter precedência!</size>",
  ui_story_40180001_10_dialog_content = "(Que dor de cabeça... Se eu soubesse que isso ia acontecer, eu não teria me importado em chamar esses três.)",
  ui_story_40180001_11_dialog_content = "(Os contos deles foram muito interessantes, mas agora eles estão se estapeando para me contar mais um...)",
  ui_story_40180001_12_dialog_content = "Fale, pessoa tola. Nos conte: quem deve contar a história primeiro?",
  ui_story_40180001_13_dialog_content = "É claro, quem tiver a melhor história deve contar primeiro.",
  ui_story_40180001_14_dialog_content = "Bom, PlayerName quer ouvir um conto de ninar. Se for muito agitado, não será possível dormir.",
  ui_story_40180001_15_dialog_content = "Então, a história mais chata deve ir por último, para provocar um sono forte.",
  ui_story_40180001_16_dialog_content = "Se é assim, como posso recusar? Eu vou primeiro...",
  ui_story_40180001_17_dialog_content = "Espere, quem tiver a melhor história deve ir primeiro...",
  ui_story_40180001_18_dialog_content = "Obviamente tem que ser eu!",
  ui_story_40180001_19_dialog_content = "Já contei uma história fantástica sobre um invasor de tumbas. Lembra, pessoa tola?",
  ui_story_40180001_20_dialog_content = "Ah, sim... eu...",
  ui_story_40180001_21_dialog_content = "Também contei ao Navegador uma história incrível sobre os espíritos nobres de meus ancestrais.",
  ui_story_40180001_22_dialog_content = "Parece que vocês, jovens, aprenderam bem com seus anciãos. Que coincidência... Eu também contei ao Navegador uma história de caçada maravilhosamente curiosa.",
  ui_story_40180001_23_dialog_content = "Parece que temos um dilema nas mãos. Melhor deixar PlayerName decidir.",
  ui_story_40180001_24_dialog_content = "PlayerName, quem você acha que contou a melhor história da última vez? Essa é a pessoa que vai contar a primeira história hoje. O que acha?",
  ui_story_40180001_25_dialog_content = "Eu... Eu...",
  ui_story_40180001_26_dialog_content = "Na verdade, eu já esqueci quase tudo o que vocês me contaram...",
  ui_story_40180001_27_dialog_content = "Quanto desrespeito! Você esqueceu?",
  ui_story_40180001_28_dialog_content = "Por favor, não se zangue... Por que não me ajuda a relembrar?",
  ui_story_40180001_29_dialog_content = "Deixe-me ver. As três histórias eram...",
  ui_story_40180001_30_option_content = "Como era Sikare Dantes?",
  ui_story_40180001_31_dialog_content = "Pessoa tola, você se esqueceu mesmo? Uma vez, encontrei um invasor de tumbas e pedi que me contasse histórias por dez dias e dez noites.",
  ui_story_40180001_32_dialog_content = "Um delas foi sobre quando ele se perdeu na Floresta de Northland. Lá, ele achou uma criança estranha, que o levou para fora da floresta.",
  ui_story_40180001_33_dialog_content = "Gostei muito dessa história, então, em troca, eu dei um tesouro preciosíssimo ao invasor de tumbas.",
  ui_story_40180001_34_dialog_content = "E era a verdade.",
  ui_story_40180001_35_dialog_content = "A história sobre tesouros... É.",
  ui_story_40180001_36_option_content = "E de Beverly?",
  ui_story_40180001_37_dialog_content = "Você se recorda, PlayerName? Você me perguntou sobre o espírito da nobreza.",
  ui_story_40180001_38_dialog_content = "Falei sobre a expedição dos meus ancestrais a Northland.",
  ui_story_40180001_39_dialog_content = "Lá, eles derrotaram os Eclipsitas e salvaram os aldeões. Apesar das grandes perdas, eles cumpriram suas obrigações aristocráticas.",
  ui_story_40180001_40_dialog_content = "Mas não aceitaram a comida e a água oferecidas pelos aldeões, o que mostra a diferença entre você e eu.",
  ui_story_40180001_41_dialog_content = "Agora que você disse, acho que lembro dessa história.",
  ui_story_40180001_42_option_content = "E a de Constantine?",
  ui_story_40180001_43_dialog_content = "Criança, eu contei a história das caçadas aos Eclipsitas. Recorda?",
  ui_story_40180001_44_dialog_content = "Enquanto eu caçava na Floresta de Northland, vi uma criatura estranha.",
  ui_story_40180001_45_dialog_content = "Eu pensei que fosse um Eclipsita, mas, após persegui-la por três horas, descobri que era uma <color=#FFB400>criança</color>.",
  ui_story_40180001_46_dialog_content = "A criança não usava muitas roupas e não queria ir para casa, então eu dei a ela meu <color=#FFB400>casaco</color>.",
  ui_story_40180001_47_dialog_content = "Então, eu <color=#FFB400>acompanhei a criança para fora da floresta</color> e ia levá-la para casa, mas a criança desobediente fugiu.",
  ui_story_40180001_48_dialog_content = "A criança nem levou o casaco! Eu fiquei preocupado que a criança se resfriasse!",
  ui_story_40180001_49_dialog_content = "Essa história... foi meio esquisita.",
  ui_story_40180001_50_dialog_content = "Bom, eu me lembro das histórias agora.",
  ui_story_40180001_51_dialog_content = "As histórias foram superinteressantes... mas não são adequadas para a hora de dormir.",
  ui_story_40180001_52_dialog_content = "É bem difícil escolher quem deve contar primeiro.",
  ui_story_40180001_53_dialog_content = "Mas, de todo modo, se tenho que escolher alguém, que seja...",
  ui_story_40180001_54_dialog_content = "Espera!",
  ui_story_40180001_55_dialog_content = "O quê?",
  ui_story_40180001_56_dialog_content = "Calma, PlayerName... Você pode escolher depois.",
  ui_story_40180001_57_dialog_content = "Eu me dei conta de uma coisa assustadora...",
  ui_story_40180001_58_dialog_content = "Err... Quê?!",
  ui_story_40180001_59_dialog_content = "Sikare e Constantine contaram histórias sobre... <color=#FFB400>uma criança de Northland</color>...",
  ui_story_40180001_60_dialog_content = "Hã? É, é verdade...",
  ui_story_40180001_61_dialog_content = "Constantine e o invasor de tumbas que Sikare mencionaram que viram a criança na Floresta de Northland e então...",
  ui_story_40180001_X61_dialog_content = "<color=#FFB400>Saíram da floresta com a criança</color>.",
  ui_story_40180001_62_dialog_content = "Correto?",
  ui_story_40180001_63_dialog_content = "Sim.",
  ui_story_40180001_64_dialog_content = "Sim, e a criança abandonou meu casaco...",
  ui_story_40180001_65_dialog_content = "O casaco não é a questão... Na verdade, eu ouvi a mesma história <color=#FFB400>na vila em que meus ancestrais foram expedicionar</color>!",
  ui_story_40180001_66_dialog_content = "O quê?!",
  ui_story_40180001_67_dialog_content = "Como é? Você também viu a criança? A criança estava resfriada?",
  ui_story_40180001_68_dialog_content = "Se ela estava resfriada ou não, também não importa!",
  ui_story_40180001_69_dialog_content = "Um tempo atrás, eu fui a Northland, à vila pela qual meus ancestrais passaram.",
  ui_story_40180001_70_dialog_content = "Fui visitar os descendentes dos aldeões que, em nome de meus ancestrais, me presentearam com comida e água.",
  ui_story_40180001_71_dialog_content = "Depois, conversamos alegremente e os aldeões me contaram umas lendas estranhas sobre Northland, incluindo...",
  ui_story_40180001_X71_dialog_content = "<color=#FFB400>Sobre uma criança estranha na Floresta de Northland</color>.",
  ui_story_40180001_72_dialog_content = "O quê? Recentemente? A criança ainda vai à floresta para brincar? Que pestinha...",
  ui_story_40180001_73_dialog_content = "E o que houve? Fale!",
  ui_story_40180001_74_dialog_content = "Beverly, o que os aldeões de Northland contaram?",
  ui_story_40180001_75_dialog_content = "Contaram que mês passado, um aldeão se perdeu na <color=#FFB400>Floresta de Northland</color> e não encontrava a saída.",
  ui_story_40180001_76_dialog_content = "Ele andou para todas as direções, mas não achou nada além de uma imensidão de árvores para todo lado.",
  ui_story_40180001_77_dialog_content = "Ele perambulou até ficar tão escuro que ele não conseguia ver o caminho com clareza.",
  ui_story_40180001_A1_dialog_content = "Então, o aldeão se sentou no chão, em desespero, achando que ia morrer sozinho na floresta.",
  ui_story_40180001_78_dialog_content = "Na verdade... Soube que ele até chorou. Era um homem forte, mas também um civil qualquer, afinal.",
  ui_story_40180001_79_dialog_content = "E depois? O que houve com ele?",
  ui_story_40180001_80_dialog_content = "Então... enquanto chorava, ele pensou em seu filho que o esperava em casa.",
  ui_story_40180001_81_dialog_content = "Sua esposa havia falecido e o filho não tinha mais ninguém. Ele pensou que jamais conseguiria escapar da floresta e em como seu filho agora não teria mãe nem pai...",
  ui_story_40180001_A2_dialog_content = "Ele entrou em desespero e começou a chamar o nome do filho.",
  ui_story_40180001_82_dialog_content = "Mas, enquanto ele chamava, inesperadamente... o filho o chamou de volta!",
  ui_story_40180001_83_dialog_content = "O quê?!",
  ui_story_40180001_84_dialog_content = "Chocado, ele olhou para trás e viu <color=#FFB400>seu filho</color> emergir da floresta densa.",
  ui_story_40180001_85_dialog_content = "E... a criança usava um <color=#FFB400>casaco estranho</color>, assim como o que Constantine está usando.",
  ui_story_40180001_86_dialog_content = "O quê?!",
  ui_story_40180001_87_dialog_content = "A criança rejeitou meu casaco e criou outro exatamente igual?",
  ui_story_40180001_88_dialog_content = "Ah... a pestinha deve ter jogado o casaco de volta, com medo que eu ficasse resfriado.",
  ui_story_40180001_89_dialog_content = "Eu devia... Eu devia trazer algo mais propício pra criança... Por que não pensei nisso? Vou encomendar um já!",
  ui_story_40180001_90_dialog_content = "A criança... Beverly, continue! Conte sobre <color=#FFB400>a criança</color> e o aldeão!",
  ui_story_40180001_91_dialog_content = "O aldeão, é claro, ficou chocado, pra dizer o mínimo.",
  ui_story_40180001_92_dialog_content = "Ele deixou escapar o nome do filho e correu para abraçá-lo.",
  ui_story_40180001_93_dialog_content = "Um rio de lágrimas descia de seus olhos e derretia a neve no solo da floresta.",
  ui_story_40180001_94_dialog_content = "A criança o abraçou alegremente, gritando: \"pai\" com animação e dizendo: \"Eu queria ir pra casa com você.\"",
  ui_story_40180001_95_dialog_content = "O aldeão estava tão feliz que nem pôde responder. Ele só assentia e se levantou quando a criança o abraçou.",
  ui_story_40180001_96_dialog_content = "Então, eles deram as mãos e seguiram adiante, um passo por vez.",
  ui_story_40180001_97_dialog_content = "Logo, <color=#FFB400>conseguiram sair da floresta</color>.",
  ui_story_40180001_98_dialog_content = "Assim que saíram da floresta, o aldeão sabia ir para casa. Felicíssimo, foi pegar o filho para comemorar.",
  ui_story_40180001_99_dialog_content = "Mas ao se virar para a criança, descobriu algo...",
  ui_story_40180001_100_dialog_content = "<anim type=Shake><color=#FFB400>Não havia ninguém atrás dele. Só neve branca o cercava...</color></anim> É isso?",
  ui_story_40180001_101_dialog_content = "Isso! Como você sabia?",
  ui_story_40180001_102_dialog_content = "Porque foi o que o invasor de tumbas disse.",
  ui_story_40180001_103_dialog_content = "Uma criança estranha o acompanhou para fora da floresta e quando ele foi agradecer, não havia nada nem ninguém.",
  ui_story_40180001_104_dialog_content = "<anim type=Shake><color=#FFB400>Ele não encontrou nem as pegadas da criança</color></anim>.",
  ui_story_40180001_105_dialog_content = "Foi o que eu imaginei! Muitas pessoas já viram essa criança!",
  ui_story_40180001_106_dialog_content = "Parece ser isso mesmo.",
  ui_story_40180001_107_dialog_content = "Espere... Não será uma histeria em massa? Uma alucinação compartilhada?",
  ui_story_40180001_108_dialog_content = "Com o frio da floresta, é possível que uma pessoa se desespere ao se perder e tenha tais ilusões.",
  ui_story_40180001_109_dialog_content = "Você diz ser possível, pessoa tola, mas...",
  ui_story_40180001_110_dialog_content = "Constantine <color=#FFB400>encontrou</color> essa criança.",
  ui_story_40180001_111_dialog_content = "É verdade... Aquela criança desobediente.",
  ui_story_40180001_112_dialog_content = "Bom, eu não sei se essa criança é real...",
  ui_story_40180001_A3_dialog_content = "O invasor de tumbas e os aldeões que você viu não inventaram... E Constantine não alucinou após matar Eclipsitas demais.",
  ui_story_40180001_113_dialog_content = "Ei! Como poderia ter sido uma alucinação? Eu tirei o casaco pra pôr na criança! Eu toquei na criança!",
  ui_story_40180001_114_dialog_content = "Beleza... Mas ainda tenho dúvidas.",
  ui_story_40180001_115_dialog_content = "Beverly, você disse agora que a criança na história era o filho do aldeão.",
  ui_story_40180001_116_dialog_content = "Ah, sim, é verdade.",
  ui_story_40180001_117_dialog_content = "Essa parte é fácil de entender. É normal confundirem uma criança com outra por causa da saudade e do desespero.",
  ui_story_40180001_118_dialog_content = "Se pensar desse modo, faz sentido...",
  ui_story_40180001_119_dialog_content = "Mas é muito estranho!",
  ui_story_40180001_120_dialog_content = "Se bem me lembro, Constantine disse que <color=#FFB400>não havia humanos</color>na Floresta de Northland.",
  ui_story_40180001_121_dialog_content = "Como uma criança poderia estar lá sozinha?",
  ui_story_40180001_122_dialog_content = "Isso mesmo, e, segundo as lendas dessa criança que ajuda os outros e <color=#FFB400>mostrou a saída da floresta</color> três vezes...",
  ui_story_40180001_123_dialog_content = "Três vezes? Não foram só duas? Com o invasor de tumbas e o aldeão?",
  ui_story_40180001_124_dialog_content = "Mas eu levei a criança para casa.",
  ui_story_40180001_125_dialog_content = "Tanto faz quantas vezes foram... A criança deve conhecer bem os caminhos da floresta.",
  ui_story_40180001_126_dialog_content = "Melhor do que o invasor de tumbas e o aldeão.",
  ui_story_40180001_127_dialog_content = "Sim. O invasor de tumbas <color=#FFB400>deixou até marcas enquanto andava</color>. Ele era um viajante superexperiente.",
  ui_story_40180001_128_dialog_content = "Mas também acabou perdido.",
  ui_story_40180001_129_dialog_content = "O aldeão também <color=#FFB400>tentou seguir para todas as direções</color>, mas não achou a saída.",
  ui_story_40180001_130_dialog_content = "Então... Não é estranho que a criança saiba andar por toda a floresta...",
  ui_story_40180001_131_dialog_content = "É mais uma questão de...",
  ui_story_40180001_132_option_content = "A criança veio do nada para ajudar os viajantes perdidos?",
  ui_story_40180001_133_dialog_content = "Ei, eu vi a criança... e ela não tinha asas!",
  ui_story_40180001_134_option_content = "Talvez ela tivesse feito buracos?",
  ui_story_40180001_135_dialog_content = "Mas eu vi a criança... e não tinha nenhuma pá!",
  ui_story_40180001_136_dialog_content = "Que estranho... Muito estranho mesmo...",
  ui_story_40180001_137_dialog_content = "Sim, certamente é muito estranho.",
  ui_story_40180001_138_dialog_content = "Mesmo sem uma saída possível, <color=#FFB400>a criança levou os perdidos para fora da floresta</color>...",
  ui_story_40180001_139_dialog_content = "E quando os aldeões viram a criança, ela estava mesmo <color=#FFB400>usando o casaco estranho de Constantine</color>...",
  ui_story_40180001_140_dialog_content = "Como uma criança criaria a réplica de uma peça de roupa tão única, em uma floresta deserta e sem vida?",
  ui_story_40180001_141_dialog_content = "Exato... Essa criança precisaria ter percorrido muitos quilômetros para criar o casaco...",
  ui_story_40180001_142_dialog_content = "Pode até ter furado o dedinho enquanto costurava os botões...",
  ui_story_40180001_143_dialog_content = "<size=42>Não é isso o que importa!</size>",
  ui_story_40180001_144_dialog_content = "Os materiais, o estilo... <color=#FFB400>Como ela faria roupas assim</color>? E tão parecidas com as de Constantine, ainda? Essa é a questão.",
  ui_story_40180001_145_dialog_content = "Então, tem algo errado com essa criança... Não! <color=#FFB400>Essa criança é a fonte de todos os problemas daqui</color>!",
  ui_story_40180001_146_dialog_content = "Ah... Beverly, mantenha sua dignidade aristocrata!",
  ui_story_40180001_147_dialog_content = "Não deixe as divagações estranhas deste velho te incomodarem.",
  ui_story_40180001_148_dialog_content = "Desculpea. Perdi a noção.",
  ui_story_40180001_149_dialog_content = "Na verdade, já que esse velho foi o único a ter <color=#FFB400>contato direto</color> com a criança, quero saber algo...",
  ui_story_40180001_150_dialog_content = "O que quer saber? A criança parecia bem habilidosa. Não me surpreende que ela saiba fazer roupas.",
  ui_story_40180001_151_dialog_content = "Não adianta perguntar pra você.",
  ui_story_40180001_152_dialog_content = "Por que não pergunta a outra pessoa? Se são de Northland, devem ter ouvido falar dela...",
  ui_story_40180001_153_dialog_content = "Pessoa tola, você sabe algo de Northland?",
  ui_story_40180001_154_dialog_content = "Ouviram falar de alguma lenda estranha como essa?",
  ui_story_40180001_155_dialog_content = "Deixa eu pensar...",
  ui_story_40180001_156_option_content = "Rainha Bethlehem?",
  ui_story_40180001_157_dialog_content = "Se tem alguém que pode saber, é ela, mas, acho que ela não terá tempo de nos ouvir.",
  ui_story_40180001_158_option_content = "E Constantine?",
  ui_story_40180001_159_dialog_content = "Você não entende, pessoa tola? É impossível se comunicar com esse velho boboca que parece obcecado por sobretudos!",
  ui_story_40180001_160_dialog_content = "Ah... Bom...",
  ui_story_40180001_161_dialog_content = "Bom, e que tal Louise?",
  ui_story_40180001_162_dialog_content = "Você deve achar estranho, mas eu também quero saber o que houve com a criança.",
  ui_story_40180001_163_dialog_content = "Louise gosta de descobrir todos os tipos de lendas. Ela também deve saber.",
  ui_story_40180001_164_dialog_content = "Certo, vou encontrá-la.",
  ui_story_40180001_165_dialog_content = "Entendi.",
  ui_story_40180001_166_dialog_content = "O invasor de tumbas viu, o aldeão de Beverly ouviu e o próprio Constantine encontrou alguma coisa estranha na Floresta de Northland... Que fenômeno peculiar.",
  ui_story_40180001_167_dialog_content = "O invasor de tumbas e o aldeão se perderam na floresta. Pensaram que jamais sairiam de lá, mas foram guiados por uma criança, que apareceu do nada.",
  ui_story_40180001_168_dialog_content = "Constantine, por outro lado, queria acompanhar a criança estranha até sua casa, mas, parece que ela também estava perdida. Só não sabia disso.",
  ui_story_40180001_169_dialog_content = "Então agora todos querem saber <color=#FFB400>quem é essa criança</color>, certo?",
  ui_story_40180001_170_dialog_content = "Nossa, é verdade!",
  ui_story_40180001_171_dialog_content = "Eu pedi que os três me contassem um conto de ninar porque eu não conseguia dormir.",
  ui_story_40180001_172_dialog_content = "Mas, depois dessa bagunça, não vou mais conseguir dormir!",
  ui_story_40180001_173_dialog_content = "Eu vou ficar até o amanhecer pensando nisso se você não souber a verdade sobre essa criança!",
  ui_story_40180001_174_dialog_content = "Entendi.",
  ui_story_40180001_175_dialog_content = "Bom, infelizmente, receio que você verá o amanhecer, então.",
  ui_story_40180001_176_dialog_content = "O quê? Mas...",
  ui_story_40180001_177_dialog_content = "Essa criança... É verdade que ela aparece nas <color=#FFB400>lendas de Northland</color>.",
  ui_story_40180001_178_dialog_content = "Muitas pessoas se perdem na imensidão da Floresta de Northland.",
  ui_story_40180001_179_dialog_content = "Seja um viajante preparado com bússola e mapa, um caçador de Eclipsitas habilidoso ou mesmo a nobre Rainha Bethlehem...",
  ui_story_40180001_180_dialog_content = "Se você entra na floresta, não consegue sair.",
  ui_story_40180001_181_dialog_content = "Porque os caminhos da floresta mudam constantemente, como se estivessem vivos.",
  ui_story_40180001_182_dialog_content = "Mudam?",
  ui_story_40180001_183_dialog_content = "Sim. Os caminhos mudam a todo minuto, a todo segundo, a todo momento.",
  ui_story_40180001_184_dialog_content = "Quem entra na floresta, sempre se perde, perde noção de direção e depois, cai em desespero.",
  ui_story_40180001_185_dialog_content = "Que horror!",
  ui_story_40180001_186_dialog_content = "Felizmente, naquela floresta mora uma criança benevolente. Ninguém sabe de onde ela veio...",
  ui_story_40180001_187_dialog_content = "Uma criança adorável, extrovertida e amigável.",
  ui_story_40180001_188_dialog_content = "Quando os viajantes se desesperam, a criança aparece e os caminhos param de mudar.",
  ui_story_40180001_189_dialog_content = "A criança pega a mão do viajante e o leva para fora da floresta.",
  ui_story_40180001_190_dialog_content = "A criança os guia até a planície nevada, ao Lago Espelho e na direção de casa.",
  ui_story_40180001_191_dialog_content = "Essa é a lenda que eu sei. Ela se chama <color=#FFB400>A Criança da Floresta Perdida</color>.",
  ui_story_40180001_192_dialog_content = "É isso.",
  ui_story_40180001_193_dialog_content = "Só isso?",
  ui_story_40180001_194_dialog_content = "É. Então, PlayerName, com relação ao seu óbvio desejo de saber quem é essa criança e o que acontece na floresta...",
  ui_story_40180001_195_dialog_content = "Ou se tiver novas perguntas após ouvir a lenda, PlayerName, tal como...",
  ui_story_40180001_A4_dialog_content = "Os caminhos da floresta realmente mudam o tempo todo? E por que eles param de mudar quando a criança aparece?",
  ui_story_40180001_196_dialog_content = "Infelizmente, <color=#FFB400>não tenho como responder</color>.",
  ui_story_40180001_197_dialog_content = "Lendas são lendas por uma razão e não precisam ser explicadas.",
  ui_story_40180001_198_dialog_content = "É um bom ponto... Vale a pena pensar nela.",
  ui_story_40180001_199_dialog_content = "Tem uma certa verdade nisso...",
  ui_story_40180001_200_dialog_content = "Também acho... que pode ser vista como um conto educativo.",
  ui_story_40180001_201_dialog_content = "Como nobre, deve-se questionar exaustivamente... Até onde for possível.",
  ui_story_40180001_202_dialog_content = "Ei! Por que vocês se convencem tão fácil?",
  ui_story_40180001_203_dialog_content = "Minha confusão aumentou ainda mais... Agora que eu não durmo mesmo!",
  ui_story_40180001_204_dialog_content = "Constantine! Você também achou estranho, não? Ainda há vários lugares estranhos nesse mundo e temos que investigá-los com o máximo de atenção, né?",
  ui_story_40180001_205_dialog_content = "Isso mesmo! Toda essa história é muito estranha!",
  ui_story_40180001_206_dialog_content = "Não é?",
  ui_story_40180001_207_dialog_content = "Se os caminhos da floresta mudavam constantemente, <color=#FFB400>por que eu não reparei em nada</color>?",
  ui_story_40180001_208_dialog_content = "Direita!",
  ui_story_40180001_209_dialog_content = "E se essa criança assombra mesmo a floresta, a floresta deve ser seu lar.",
  ui_story_40180001_A5_dialog_content = "Mas se os caminhos mudam sempre, como ela vai para casa?",
  ui_story_40180001_210_dialog_content = "Erm... Verdade!",
  ui_story_40180001_211_dialog_content = "E se a criança não for pra casa, como o pestinha pôde ter feito uma cópia do meu casaco?",
  ui_story_40180001_212_dialog_content = "Erm... É!",
  ui_story_40180001_213_dialog_content = "Não, não, não... Com certeza o casaco que o aldeão viu era só uma ilusão. A criança deve estar tremendo de frio!",
  ui_story_40180001_214_dialog_content = "Hã?",
  ui_story_40180001_215_dialog_content = "Não há tempo a perder... Preciso ir para Northland, levar algo para a criança vestir!",
  ui_story_40180001_X215_dialog_content = "Se ela continuar zanzando daquele jeito, acabará ficando doente!",
  ui_story_40180001_216_dialog_content = "<size=36>Você não entendeu mesmo, não é?</size>"
}
